    <div className="containmentOrbital"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="18"/><circle cx="50" cy="50" r="29"/><circle cx="50" cy="50" r="39"/>{agents.map((a:any,i:number)=>{const p=orbitalPoint(i,agents.length);return <path key={a.id??a.external_id} d={`M50 50 Q${(50+p.x)/2} ${(50+p.y)/2-3} ${p.x} ${p.y}`} className={"containEdge "+(a.status==="healthy"?"healthy":"restricted")}/>})}</svg><div className="containCore"><NodraLogo className="dashboardCoreLogo"/></div>{agents.map((a:any,i:number)=>{const p=orbitalPoint(i,agents.length);return <Link href="/agents" key={a.id??a.external_id} className={"containAgent tone"+(i%5)} style={{left:p.x+"%",top:p.y+"%"}}><span><Bot/></span><b>{a.name??a.external_id}</b><small>{a.status}</small></Link>})}{!agents.length?<div className="networkEmptyState"><Bot/><strong>No protected agents</strong></div>:null}<div className="containStatus"><b>Workspace Status</b><span>{healthy} / {agents.length} Agents Healthy</span><i><em style={{width:(agents.length?healthy/agents.length*100:100)+"%"}}/></i></div></div>
